    """Срок резерва истёк."""

    def __init__(self, order_id: str) -> None:
        super().__init__(order_id, f"reservation for order {order_id!r} has expired")


class ReservationStateError(ReservationError):
    """Операция недопустима в текущем статусе резерва."""

    def __init__(self, order_id: str, status: object = None) -> None:
        shown = getattr(status, "value", status)
        super().__init__(
            order_id, f"operation is not allowed for reservation of order {order_id!r} ({shown})"
        )
        self.status = status


