def reserve(
    self,
    order_id: str,
    lines: Iterable[tuple[str, str, int] | ReservationLine],
    ttl: timedelta | None = None,
) -> Reservation:
    """Резервирует товар под заказ сразу по всем строкам (всё или ничего)."""
    _validate_code(order_id, "order_id")
    ttl = _validate_ttl(ttl, DEFAULT_RESERVATION_TTL)
    parsed = tuple(_parse_line(line) for line in lines)
    if not parsed:
        raise ValidationError("reservation must have at least one line")
    for line in parsed:
        self._check_position(line.warehouse, line.sku)
        _validate_qty(line.qty)
    if order_id in self._reservations:
        raise DuplicateReservationError(order_id)
    now = self._clock.now()
    for (warehouse, sku), total in _totals(parsed).items():
        free = self._free(warehouse, sku, now)
        if total > free:
            raise InsufficientStockError(warehouse, sku, total, free)
    record = ReservationRecord(order_id, parsed, now, now + ttl)
    self._reservations[order_id] = record
    expires = format_timestamp(record.expires_at)
    for line in parsed:
        self._log.append(
            now, "RESERVE", order=order_id, wh=line.warehouse, sku=line.sku, qty=line.qty,
            expires=expires,
        )
    logger.info("reserved order %s (%d lines)", order_id, len(parsed))
    return record.snapshot(now)

def confirm(self, order_id: str) -> Reservation:
    """Превращает активный резерв в отгрузку."""
    now = self._clock.now()
    record = self._active_record(order_id, now)
    totals = _totals(record.lines)
    for (warehouse, sku), total in totals.items():
        current = self._store.get_qty(warehouse, sku)
        if total > current:
            raise InsufficientStockError(warehouse, sku, total, current)
    for (warehouse, sku), total in totals.items():
        self._store.set_qty(warehouse, sku, self._store.get_qty(warehouse, sku) - total)
    record.status = ReservationStatus.CONFIRMED
    for line in record.lines:
        self._log.append(
            now, "ISSUE", wh=line.warehouse, sku=line.sku, qty=line.qty, ref=order_id
        )
    self._log.append(now, "RESERVE_CONFIRM", order=order_id)
    logger.info("confirmed reservation of order %s", order_id)
    return record.snapshot(now)

def cancel(self, order_id: str) -> Reservation:
    """Освобождает резерв. Повторная отмена (и отмена истёкшего) ничего не делает."""
    now = self._clock.now()
    record = self._record(order_id)
    status = record.effective_status(now)
    if status is ReservationStatus.CONFIRMED:
        raise ReservationStateError(order_id, status)
    if status is ReservationStatus.ACTIVE:
        record.status = ReservationStatus.CANCELLED
        self._log.append(now, "RESERVE_CANCEL", order=order_id)
        logger.info("cancelled reservation of order %s", order_id)
    return record.snapshot(now)

def extend(self, order_id: str, ttl: timedelta) -> Reservation:
    """Продлевает активный резерв на ``ttl`` от его текущего срока."""
    ttl = _validate_ttl(ttl, None)
